world node {
    use aap:caps/types@0.1.0.{conversation-context, response-result};

    import aap:caps/kb-read@0.1.0;
    import aap:caps/tool-llm@0.1.0;

    export run: func(ctx: conversation-context) -> response-result;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        use crate::aap::caps::kb_read;
        use crate::aap::caps::tool_llm::{self, Reply};

        // The contract `requires len(question) <= 512` holds of every input we
        // are given, so the question is already bounded on entry.

        let system = "You are a customer-support agent. Answer the user's \
                      question using the supplied knowledge. When you need an \
                      additional fact from the knowledge base, ask for the \
                      `lookup` tool; otherwise reply with the final answer.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\n\nKnowledge:\n");
        if ctx.knowledge.is_empty() {
            prompt.push_str("(none provided)\n");
        } else {
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);

        // Bounded tool-orchestration loop. The only tool interface in this
        // node's world is kb-read, so `lookup` is the only invocable tool;
        // any other requested tool is refused as out-of-scope.
        const MAX_ROUNDS: usize = 8;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nTool `lookup` results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "requested tool `{}` is not in this node's scope",
                                req.tool
                            ),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge within the \
                      permitted number of rounds"
                .to_string(),
        })
    }
}

export!(Node);
```

